/* =====================================================================
   DỮ LIỆU MẪU: 227 sản phẩm, 9 loại (CPU, Mainboard, RAM, VGA, SSD, PSU, Case, Tản nhiệt, Phụ kiện)
   kèm thông số kỹ thuật (bảng ThongSoKyThuats) theo đúng tên thông số của seed gốc.

   Cách dùng: trong SSMS, chuột phải vào DATABASE của dự án > New Query,
   dán toàn bộ file này rồi Execute.
   Chạy lại nhiều lần được: dòng nào đã có sẽ bị bỏ qua.

   Lưu ý: giá, tồn kho và thông số là DỮ LIỆU MẪU để kiểm thử website,
   không phải bảng giá hay thông số chính thức của hãng.
   Ảnh: AnhDaiDien trỏ tới /images/products/<tên-file>.jpg; tải ảnh bằng
   Tools/ImageFetcher/fetch_images.py.
   ===================================================================== */

USE WebLinhKien;
GO
SET NOCOUNT ON;
GO

/* 1. Danh mục mới */
INSERT INTO dbo.DanhMucs (MaDanhMuc, TenDanhMuc, Ordering)
SELECT v.Ma, v.Ten, v.Ord
FROM (VALUES
    (N'TANNHIET', N'Tản nhiệt', 9)
) AS v(Ma, Ten, Ord)
WHERE NOT EXISTS (SELECT 1 FROM dbo.DanhMucs d WHERE d.MaDanhMuc = v.Ma);
GO

